  v_id NUMBER; v_pago NUMBER; v_vencidas NUMBER;
BEGIN
  pkg_credito.desembolsar(25, '4014784906', 'Luis Burneo', v_id, TRUNC(SYSDATE) - 701);
  SELECT COUNT(*) INTO v_vencidas FROM tb_cuota WHERE id_credito = v_id AND fecha_vencimiento < TRUNC(SYSDATE);
  FOR c IN (SELECT numero, valor_cuota, fecha_vencimiento FROM tb_cuota
             WHERE id_credito = v_id AND fecha_vencimiento < TRUNC(SYSDATE) ORDER BY numero) LOOP
    EXIT WHEN c.numero > v_vencidas - 0;
    pkg_credito.registrar_pago(v_id, c.valor_cuota, 'VENTANILLA', 'REC-' || LPAD(v_id, 5, '0') || '-' || c.numero, 'Caja', v_pago,
                               CAST(c.fecha_vencimiento AS TIMESTAMP) + NUMTODSINTERVAL(-4, 'DAY') + INTERVAL '11' HOUR);
  END LOOP;
END;
/
