-- Gestiones de cobranza (6.2)
UPDATE tb_credito SET estado = 'JUDICIAL' WHERE id_solicitud = 39;
UPDATE tb_credito SET estado = 'JUDICIAL' WHERE id_solicitud = 40;
UPDATE tb_alerta_cartera SET atendida = 'S' WHERE id_credito IN (SELECT id_credito FROM tb_gestion_cobranza WHERE resultado = 'PROMESA_PAGO');
BEGIN pkg_credito.calcular_provisiones(TO_CHAR(SYSDATE, 'YYYY-MM')); END;
/
